<?php
use App\Core\Database as DB;use App\Services\StudentService as S;
$courses=S::courses($student);$total=0;$complete=0;$progressSum=0;foreach($courses as $course){foreach($course['modules'] as $m){$total+=$m['lessons_total'];$complete+=$m['lessons_done'];foreach($m['lessons'] as $l){$progressSum+=$l['percent'];}}}$percent=$total?(int)round($progressSum/$total):0;
$attemptCount=(int)DB::val("SELECT COUNT(*) FROM test_attempts WHERE student_id=? AND result<>'pending'",[$student]);$page=max(1,min(max(1,(int)ceil($attemptCount/15)),(int)($_GET['page']??1)));$offset=($page-1)*15;$attempts=DB::all("SELECT a.*,COALESCE(tr.title,t.title) AS title FROM test_attempts a JOIN tests t ON t.id=a.test_id LEFT JOIN test_translations tr ON tr.test_id=t.id AND tr.language_id=(SELECT id FROM languages WHERE code=?) WHERE a.student_id=? AND a.result<>'pending' ORDER BY a.id DESC LIMIT 15 OFFSET $offset",[\App\Services\TranslationService::currentCode(),$student]);
page_header('My Progress'); ?>
<section class="card progress-summary"><div class="progress-ring p<?= $percent ?>"><span><?= $percent ?>%</span></div><div><h2><?= e(tr('Overall progress')) ?></h2><p class="muted"><?= $complete ?> / <?= $total ?> <?= e(tr('Completed lessons')) ?></p><a class="btn btn-primary" href="courses.php"><?= e(tr('Continue Learning')) ?></a></div></section>
<?php foreach($courses as $course): ?><section class="card"><div class="card-heading"><h2><?= e($course['name']) ?></h2><span class="pill ok"><?= $course['percent'] ?>%</span></div><?php foreach($course['modules'] as $m): ?><div class="progress-row"><span class="module-number <?= $m['passed']?'done':'' ?>"><?= icon($m['passed']?'check':($m['unlocked']?'play':'lock')) ?></span><div><strong><?= e($m['title']) ?></strong><div class="progress-track"><div class="progress-fill w<?= $m['percent'] ?>"></div></div></div><b><?= $m['percent'] ?>%</b></div><?php endforeach; ?></section><?php endforeach; ?>
<section class="card"><h2><?= e(tr('Test history')) ?></h2><div class="table-wrap"><table><thead><tr><?php foreach(['Test title','Score','Result','Submitted','Actions'] as $label): ?><th><?= e(tr($label)) ?></th><?php endforeach; ?></tr></thead><tbody><?php foreach($attempts as $a): ?><tr><td><?= e($a['title']) ?></td><td><?= (float)$a['percentage'] ?>%</td><td><span class="pill <?= e($a['result']) ?>"><?= e(tr($a['result'])) ?></span></td><td><?= e(fmt_dt($a['submitted_at'])) ?></td><td><a class="btn btn-sm" href="tests.php?result=<?= (int)$a['id'] ?>"><?= e(tr('View')) ?></a></td></tr><?php endforeach; ?><?php if(!$attempts): ?><tr><td colspan="5"><?= e(tr('No test attempts yet.')) ?></td></tr><?php endif; ?></tbody></table></div></section><div class="pagination"><span><?= $attemptCount ?> <?= e(tr('Test attempts')) ?></span><nav><?php foreach(['Previous'=>$page-1,'Next'=>$page+1] as $label=>$n):if($n<1||$n>ceil($attemptCount/15))continue; ?><a class="btn" href="?page=<?= $n ?>"><?= e(tr($label)) ?></a><?php endforeach; ?></nav></div><?php page_footer();
